// What the printable documentation holds, and in which order: the site's own
// sidebar, as Starlight resolves it for a language (labels translated,
// autogenerated groups expanded), so the order has one source of truth,
// astro.config.mjs. Pure: it takes the sidebar and returns the book.
//
// Left out: every link that is not a page of the docs (the print page
// itself), and every group left with no page.

/** A sidebar entry, as Starlight's route data gives it. */
export type SidebarEntry =
  | { type: "link"; label: string; href: string }
  | { type: "group"; label: string; entries: SidebarEntry[] };

/** A page of the book: its entry id, its title in the sidebar, and its anchor. */
export interface BookPage {
  kind: "page";
  id: string;
  label: string;
  href: string;
  anchor: string;
}

/** A part of the book: a sidebar group that kept at least one page. */
export interface BookPart {
  kind: "part";
  label: string;
  children: BookNode[];
}

export type BookNode = BookPage | BookPart;

/** A page in reading order, with the parts it sits in. */
export interface PageInOrder extends BookPage {
  trail: string[];
}

/** The entry id of a site path (`/docs/es/guide/x/` → `es/guide/x`), or null
 * when the path is not under the site's base. */
export function idOf(href: string, base: string): string | null {
  const root = base.endsWith("/") ? base : `${base}/`;
  if (!href.startsWith(root)) return null;
  const id = href.slice(root.length).replace(/\/+$/, "");
  return id === "" ? null : id;
}

/** The fragment a page gets in the book: its id with dashes for slashes. */
export function anchorOf(id: string): string {
  return `page-${id.replace(/[^a-z0-9]+/gi, "-")}`;
}

/**
 * The book of a sidebar: its groups as parts and its pages, in the sidebar's
 * order. `isPage` says whether an entry id is a page of the docs (one that
 * can be rendered); links to anything else are dropped, and so are parts
 * left empty.
 */
export function bookOf(
  sidebar: SidebarEntry[],
  base: string,
  isPage: (id: string) => boolean,
): BookNode[] {
  return sidebar.flatMap((entry): BookNode[] => {
    if (entry.type === "group") {
      const children = bookOf(entry.entries, base, isPage);
      return children.length ? [{ kind: "part", label: entry.label, children }] : [];
    }
    const id = idOf(entry.href, base);
    if (id === null || !isPage(id)) return [];
    return [{ kind: "page", id, label: entry.label, href: entry.href, anchor: anchorOf(id) }];
  });
}

/** The book's pages in reading order, each with the parts it sits in. */
export function pagesOf(book: BookNode[], trail: string[] = []): PageInOrder[] {
  return book.flatMap((node) =>
    node.kind === "page" ? [{ ...node, trail }] : pagesOf(node.children, [...trail, node.label]),
  );
}
